<?php
require_once __DIR__.'/includes/db.php';$pdo=db();$albumId=max(0,(int)($_GET['album_id']??0));$album=null;$photos=[];if($albumId){$s=$pdo->prepare('SELECT * FROM albums WHERE id=?');$s->execute([$albumId]);$album=$s->fetch();if($album){$s=$pdo->prepare('SELECT * FROM photos WHERE album_id=? ORDER BY id DESC');$s->execute([$albumId]);$photos=$s->fetchAll();}}$albums=$pdo->query('SELECT a.*,COUNT(p.id) photo_count FROM albums a LEFT JOIN photos p ON p.album_id=a.id GROUP BY a.id ORDER BY a.album_date DESC')->fetchAll();$pageTitle=$album?h($album['title']):'Фотоальбомы';require __DIR__.'/includes/header.php';
?><section class="mx-auto max-w-7xl px-4 py-14"><p class="font-bold uppercase tracking-widest text-red-500">Моменты большого спорта</p><h1 class="mt-2 text-4xl font-black"><?=$album?h($album['title']):'Фотоальбомы'?></h1><?php if($album):?><a class="mt-5 inline-block text-red-400" href="gallery.php">← Все альбомы</a><?php if(!$photos):?><div class="panel mt-8 rounded-2xl p-8 text-gray-400">В альбоме пока нет фотографий. Следите за обновлениями.</div><?php else:?><div class="mt-8 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4"><?php foreach($photos as $i=>$photo):?><button class="photo-open group relative aspect-square overflow-hidden rounded-xl bg-neutral-800" data-src="<?=h($photo['path'])?>" data-caption="<?=h($photo['caption'])?>"><img class="h-full w-full object-cover transition group-hover:scale-105" src="<?=h($photo['path'])?>" alt="<?=h($photo['caption']?:'Фотография из альбома')?>" loading="lazy"><span class="absolute inset-0 grid place-items-center bg-black/0 text-3xl opacity-0 transition group-hover:bg-black/30 group-hover:opacity-100"><i class="fa-solid fa-magnifying-glass-plus"></i></span></button><?php endforeach;?></div><?php endif;?><?php else:?><p class="mt-3 text-gray-400">Фотографии с тренировок, соревнований и событий школы.</p><div class="mt-8 grid gap-5 sm:grid-cols-2 lg:grid-cols-3"><?php foreach($albums as $a):?><a href="gallery.php?album_id=<?=$a['id']?>" class="panel group overflow-hidden rounded-2xl"><div class="relative grid aspect-[4/3] place-items-center bg-gradient-to-br from-neutral-800 to-red-950"><?php if($a['cover']):?><img src="<?=h($a['cover'])?>" alt="<?=h($a['title'])?>" class="h-full w-full object-cover"><?php else:?><i class="fa-solid fa-images text-6xl text-white/20"></i><?php endif;?><span class="absolute bottom-3 right-3 rounded-full bg-black/70 px-3 py-1 text-xs"><?=$a['photo_count']?> фото</span></div><div class="p-5"><p class="text-sm text-red-400"><?=h(date('d.m.Y',strtotime($a['album_date'])))?></p><h2 class="mt-2 text-xl font-bold group-hover:text-red-300"><?=h($a['title'])?></h2></div></a><?php endforeach;?></div><?php endif;?></section><div id="lightbox" class="fixed inset-0 z-50 hidden items-center justify-center bg-black/95 p-4" role="dialog" aria-modal="true"><button id="lightClose" class="absolute right-6 top-4 text-4xl" aria-label="Закрыть">×</button><button id="lightPrev" class="absolute left-4 top-1/2 text-4xl">‹</button><figure class="max-h-[90vh] max-w-[90vw] text-center"><img id="lightImage" class="mx-auto max-h-[80vh] max-w-full object-contain" alt=""><figcaption id="lightCaption" class="mt-3"></figcaption></figure><button id="lightNext" class="absolute right-4 top-1/2 text-4xl">›</button></div><script>const photos=[...document.querySelectorAll('.photo-open')],lb=document.getElementById('lightbox');let pi=0;function showPhoto(n){pi=(n+photos.length)%photos.length;const b=photos[pi];document.getElementById('lightImage').src=b.dataset.src;document.getElementById('lightImage').alt=b.dataset.caption||'Фотография';document.getElementById('lightCaption').textContent=b.dataset.caption;lb.classList.remove('hidden');lb.classList.add('flex')}photos.forEach((b,i)=>b.onclick=()=>showPhoto(i));function hideLight(){lb.classList.add('hidden');lb.classList.remove('flex')}document.getElementById('lightClose').onclick=hideLight;document.getElementById('lightPrev').onclick=()=>showPhoto(pi-1);document.getElementById('lightNext').onclick=()=>showPhoto(pi+1);lb.onclick=e=>{if(e.target===lb)hideLight()};document.addEventListener('keydown',e=>{if(e.key==='Escape')hideLight();if(!lb.classList.contains('hidden')&&e.key==='ArrowRight')showPhoto(pi+1);if(!lb.classList.contains('hidden')&&e.key==='ArrowLeft')showPhoto(pi-1)});</script><?php require __DIR__.'/includes/footer.php';
